}

return <SignInScreen />;

const client = axios.create({
  baseURL: `${BASE_URL_ENV}/api/`,
  headers,
  timeout: 13000,
});

if (token) {
  config.headers.Authorization =
    `Bearer ${token}`;
}

export const getBuildingWmslink =
  async () => {
    return await client.get(
      URLS.wsBuildingLink
    );
  };

export const uploadBuildingData =
  async data => {
    return await client.post(
      URLS.uploadBuildingData, data
    );
  };

